using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Nexora.Domain.Catalog;
namespace Nexora.Infrastructure.Persistence;
public sealed class ProfessionalConfiguration:IEntityTypeConfiguration<Professional>{public void Configure(EntityTypeBuilder<Professional>b){b.ToTable("professionals", DatabaseSchemas.Catalog);b.HasKey(x=>x.Id);b.HasAlternateKey(x=>new{x.TenantId,x.Id});b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Email).HasMaxLength(320);b.Property(x=>x.Phone).HasMaxLength(40);b.HasIndex(x=>new{x.TenantId,x.Name});b.HasOne<Nexora.Domain.Tenancy.Tenant>().WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class ServiceConfiguration:IEntityTypeConfiguration<Service>{public void Configure(EntityTypeBuilder<Service>b){b.ToTable("services", DatabaseSchemas.Catalog);b.HasKey(x=>x.Id);b.HasAlternateKey(x=>new{x.TenantId,x.Id});b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.Price).HasPrecision(18,2);b.HasIndex(x=>new{x.TenantId,x.Name});b.HasOne<Nexora.Domain.Tenancy.Tenant>().WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class ProfessionalServiceConfiguration:IEntityTypeConfiguration<ProfessionalService>{public void Configure(EntityTypeBuilder<ProfessionalService>b){b.ToTable("professional_services", DatabaseSchemas.Catalog);b.HasKey(x=>new{x.TenantId,x.ProfessionalId,x.ServiceId});b.HasOne(x=>x.Professional).WithMany(x=>x.Services).HasForeignKey(x=>new{x.TenantId,x.ProfessionalId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.Service).WithMany(x=>x.Professionals).HasForeignKey(x=>new{x.TenantId,x.ServiceId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Cascade);b.HasIndex(x=>new{x.TenantId,x.ServiceId});}}
